import{_ as s,l as i,o as e,c as l,v as t,p as n,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"位图与位集","description":"","frontmatter":{"title":"位图与位集","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bitset.md","filePath":"cs/bitset.md","lastUpdated":1789023840000}'),h={name:"cs/bitset.md"};function m(_,a,f,u,A,b){const r=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="位图与位集" tabindex="-1">位图与位集 <a class="header-anchor" href="#位图与位集" aria-label="Permalink to &quot;位图与位集&quot;">​</a></h1><div class="epigraph"><p>论域是一小段整数时，存在位里：交并差是字级与或非，比指针集合少两个数量级的常数。</p><footer>—— 据 Knuth, The Art of Computer Programming 卷 4A；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/mo-algorithm">上一课</a>用计数或哈希维护区间状态，每个元素仍是一条「在/不在」记录。论域若是 \\([0,U)\\) 且 \\(U\\) 不太大，不必哈希。<a href="/cs/array-random-access">数组</a>按字寻址。本课不重排询问。缺口是位图 / bitset：用 \\(\\lceil U/w\\rceil\\) 个机器字表示子集，\\(w\\) 为字宽，交并扫描字。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>集合操作在链表或哈希表上按 \\(n\\) 走。位图：第 \\(x\\) 位表示 \\(x\\) 是否在集合中，查找/插入/删除 \\(\\Theta(1)\\) 字操作（移位与掩码）。并、交、差：对每个字 <code>or</code>/<code>and</code>/<code>and-not</code>，时间 \\(\\Theta(U/w)\\)。缺口不是新的集合公理，而是<strong>把存在性压进位、把循环交给字级并行</strong>。</p><p>稀疏时 \\(U\\gg n\\)，位图浪费空间——下一课稀疏集合。本课假定 \\(U\\) 与 \\(n\\) 同阶或 \\(U\\) 固定（字符集、小值域）。</p><p><span class="marginnote">Knuth 卷 4A 对位技巧与人口计数有系统处理。硬件 <code>popcount</code> 让「集合大小」也变成按字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>下标 \\(x\\) 的字号 \\(\\lfloor x/w\\rfloor\\)，位 \\(x\\bmod w\\)。迭代「下一个 1」可用 <code>ctz</code>（尾零计数）扫字。区间置位可用字填充加两端掩码，不必循环 \\(r-l\\) 次比特。</p>',9)),(e(),n(p,null,{default:o(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20X%5B%22%E5%85%83%E7%B4%A0%20x%22%5D%20--%3E%20WORD%5B%22%E5%AD%97%20floor(x%2Fw)%22%5D%0A%20%20WORD%20--%3E%20BIT%5B%22%E4%BD%8D%20x%20mod%20w%22%5D%0A%20%20AND%5B%22%E5%AD%97%E7%BA%A7%20AND%22%5D%20--%3E%20INTER%5B%22%E4%BA%A4%E9%9B%86%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与<a href="/cs/bloom-filter">布隆过滤器</a>：Bloom 允许假阳性且不存论域下标；位图精确，论域必须能映射到 \\(0..U-1\\)。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>cache：连续字扫交并，带宽决定时间，符合<a href="/cs/locality-principle">局部性</a>。图的邻接矩阵行是位图时，相交计数是矩阵乘法的位版，本课只点名。不要用位图表示任意字符串键——先要整数化。</p><p>可持久化位图可做路径复制或只读共享页，那是后课持久化结构，本课原地更新。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>\\(U\\) 过大不可分配。并发改同一字要原子位运算，课序后段再谈。本课不把 SIMD 全套指令当正文。值域大、元素少：稀疏集合用紧数组 + 稠密下标。</p><p>后课默认：小论域精确集用位图。稀疏整数集用 sparse set。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>bitset：精确、字级交并，时间 \\(\\Theta(U/w)\\)。</li><li>论域要小或固定；稀疏换下一课。</li><li>出处：Knuth, TAOCP 卷 4A；Cormen et al.。</li></ul>',9))])}const D=s(h,[["render",m]]);export{x as __pageData,D as default};
